 for(const [needle,repl,tplOnly] of reps){let i=-1,out='';let last=0;while((i=s.indexOf(needle,i+1))>=0){if(tplOnly&&!inTpl(s,i))continue;out+=s.slice(last,i)+repl;last=i+needle.length;n++;}out+=s.slice(last);s=out;}
